import { createContext, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
import { NavLink, Navigate, Outlet, Route, Routes, useLocation, useNavigate } from "react-router-dom";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { AlertCircle, BriefcaseBusiness, Check, ChevronDown, ChevronUp, Download, FileText, FolderKanban, Globe2, Home, Languages, LoaderCircle, LogOut, Menu, Plus, RefreshCw, Save, Settings, Trash2, Upload, UserRound, X } from "lucide-react";
import { ApiError, api, authExpiredEvent, downloadApiFile, getAccessToken, setAccessToken, uploadApiFile } from "./api";
import { ContentManager } from "./ContentManager";
import { HighlightEditor, type Highlight } from "./HighlightEditor";
import { SiteManager } from "./SiteManager";
import { AdminLocaleProvider, localizeAdminError, useAdminI18n, type AdminLocale } from "./i18n";

type UiLocale = AdminLocale;
type ContentLocale = "ar" | "en";
type AuthContextValue = { token: string | null; login: (value: string) => void; logout: () => Promise<void>; uiLocale: UiLocale; setUiLocale: (value: UiLocale) => void };
const AuthContext = createContext<AuthContextValue | null>(null);
const useAuth = () => useContext(AuthContext)!;

const navigationCopy = {
  ar: { dashboard: "الرئيسية", owner: "بياناتي", projects: "المشاريع", content: "المحتوى المهني", profiles: "البروفايلات", resume: "محرر السيرة", sites: "المواقع والنشر", settings: "الإعدادات", logout: "تسجيل الخروج", panel: "لوحة إدارة السيرة", skip: "انتقل إلى المحتوى", menu: "فتح القائمة" },
  en: { dashboard: "Dashboard", owner: "My details", projects: "Projects", content: "Professional content", profiles: "Profiles", resume: "Resume editor", sites: "Sites & publishing", settings: "Settings", logout: "Sign out", panel: "Resume administration", skip: "Skip to content", menu: "Open menu" }
} as const;

export function App() {
  const [token, setToken] = useState<string | null>(() => getAccessToken());
  const [uiLocale, setUiLocale] = useState<UiLocale>("ar");
  useEffect(() => {
    const handleAuthExpired = () => setToken(null);
    window.addEventListener(authExpiredEvent, handleAuthExpired);
    return () => window.removeEventListener(authExpiredEvent, handleAuthExpired);
  }, []);
  useEffect(() => {
    document.documentElement.lang = uiLocale;
    document.documentElement.dir = uiLocale === "ar" ? "rtl" : "ltr";
  }, [uiLocale]);
  const value = useMemo<AuthContextValue>(() => ({ token, login: value => { setAccessToken(value); setToken(value); }, logout: async () => { try { await api("/api/v1/auth/logout", { method: "POST" }); } finally { setAccessToken(null); setToken(null); } }, uiLocale, setUiLocale }), [token, uiLocale]);
  return <AuthContext.Provider value={value}><AdminLocaleProvider locale={uiLocale}><div lang={uiLocale} dir={uiLocale === "ar" ? "rtl" : "ltr"}>{token ? <AuthenticatedApp /> : <Login />}</div></AdminLocaleProvider></AuthContext.Provider>;
}

type LoginFields = { email: string; password: string };

function Login() {
  const { login, uiLocale, setUiLocale } = useAuth();
  const { l } = useAdminI18n();
  const loginSchema = z.object({ email: z.email(l("أدخل بريدًا صحيحًا", "Enter a valid email address")), password: z.string().min(1, l("كلمة المرور مطلوبة", "Password is required")) });
  const { register, handleSubmit, formState: { errors, isSubmitting }, setError } = useForm<LoginFields>({ resolver: zodResolver(loginSchema) });
  const submit = async (values: LoginFields) => { try { const result = await api<{ accessToken: string }>("/api/v1/auth/login", { method: "POST", body: JSON.stringify(values) }); login(result.accessToken); } catch (error) { setError("root", { message: error instanceof ApiError ? localizeAdminError(error, l) : l("تعذر تسجيل الدخول", "Unable to sign in") }); } };
  return <main className="login-page"><section className="login-brand"><span className="login-mark">{l("السيرة الذاتية", "Resume")}</span><div><h1>{l("مهندس برمجيات", "Software Engineer")}<br /><bdi>{l("Flutter وخدمات خلفية باستخدام .NET", "Flutter &amp; .NET Backend")}</bdi></h1><p>{l("مساحة خاصة لإدارة الحقائق المهنية، البروفايلات الموجّهة، المواقع وملفات السيرة دون تعريض المسودات للعامة.", "A private workspace for professional facts, targeted profiles, sites, and resumes without exposing drafts.")}</p></div><span>{l("للمالك فقط · لا يوجد تسجيل عام", "Owner only · No public sign-up")}</span></section><section className="login-panel"><form className="login-form" onSubmit={handleSubmit(submit)} noValidate><button className="button button-secondary" type="button" onClick={() => setUiLocale(uiLocale === "ar" ? "en" : "ar")}>{uiLocale === "ar" ? "English" : "العربية"}</button><h2>{l("تسجيل دخول المالك", "Owner sign in")}</h2><p className="muted">{l("تبقى الجلسة محفوظة داخل علامة التبويب بعد تحديث الصفحة، وتنتهي خلال 30 دقيقة.", "The session survives a page refresh in this tab and expires after 30 minutes.")}</p>{errors.root && <div className="notice" role="alert"><AlertCircle size={18} aria-hidden="true" /> {errors.root.message}</div>}<div className="field"><label htmlFor="email">{l("البريد الإلكتروني", "Email")}</label><input id="email" dir="ltr" type="email" autoComplete="username" {...register("email")} aria-invalid={!!errors.email} />{errors.email && <p className="field-error">{errors.email.message}</p>}</div><div className="field"><label htmlFor="password">{l("كلمة المرور", "Password")}</label><input id="password" dir="ltr" type="password" autoComplete="current-password" {...register("password")} aria-invalid={!!errors.password} />{errors.password && <p className="field-error">{errors.password.message}</p>}</div><button className="button button-primary button-wide" disabled={isSubmitting}>{isSubmitting && <LoaderCircle size={18} className="animate-spin" aria-hidden="true" />}{l("دخول آمن", "Sign in securely")}</button></form></section></main>;
}

function AuthenticatedApp() {
  return <Routes><Route element={<Shell />}><Route index element={<Dashboard />} /><Route path="owner" element={<OwnerPage />} /><Route path="projects" element={<ProjectsPage />} /><Route path="content" element={<ContentPage />} /><Route path="profiles" element={<ProfilesPage />} /><Route path="resume" element={<ResumeEditor />} /><Route path="sites" element={<SitesPage />} /><Route path="settings" element={<SettingsPage />} /></Route><Route path="*" element={<Navigate to="/" replace />} /></Routes>;
}

const navigation = [
  { to: "/", key: "dashboard", icon: Home, end: true }, { to: "/owner", key: "owner", icon: UserRound }, { to: "/projects", key: "projects", icon: FolderKanban }, { to: "/content", key: "content", icon: BriefcaseBusiness }, { to: "/profiles", key: "profiles", icon: FileText }, { to: "/resume", key: "resume", icon: Download }, { to: "/sites", key: "sites", icon: Globe2 }, { to: "/settings", key: "settings", icon: Settings }
] as const;

function Shell() {
  const { uiLocale, setUiLocale, logout } = useAuth(); const [open, setOpen] = useState(false); const location = useLocation(); const t = navigationCopy[uiLocale];
  const current = navigation.find(x => ("end" in x && x.end) ? location.pathname === x.to : location.pathname.startsWith(x.to));
  return <div className="app-shell"><a className="skip-link" href="#admin-main">{t.skip}</a><aside className={`sidebar ${open ? "open" : ""}`} aria-label={uiLocale === "ar" ? "التنقل الإداري" : "Admin navigation"}><div className="sidebar-brand">{t.panel}</div><nav className="sidebar-nav">{navigation.map(item => { const Icon = item.icon; return <NavLink key={item.to} to={item.to} end={"end" in item ? item.end : false} onClick={() => setOpen(false)} className={({ isActive }) => `nav-link ${isActive ? "active" : ""}`}><Icon size={20} aria-hidden="true" /><span>{t[item.key]}</span></NavLink>; })}</nav><div className="sidebar-footer"><button className="nav-link" onClick={() => setUiLocale(uiLocale === "ar" ? "en" : "ar")}><Languages size={20} aria-hidden="true" />{uiLocale === "ar" ? "English UI" : "واجهة عربية"}</button><button className="nav-link" onClick={() => void logout()}><LogOut size={20} aria-hidden="true" />{t.logout}</button></div></aside><header className="topbar"><button className="icon-button menu-button" onClick={() => setOpen(!open)} aria-expanded={open} aria-label={t.menu}>{open ? <X aria-hidden="true" /> : <Menu aria-hidden="true" />}</button><span className="topbar-title">{current ? t[current.key] : t.panel}</span><div className="topbar-actions"><span className="status status-success">{uiLocale === "ar" ? "جلسة محمية" : "Protected session"}</span></div></header><main id="admin-main" className="main"><Outlet /></main></div>;
}

type Translation = { locale: "ar" | "en"; fullName?: string; defaultHeadline?: string; defaultSummary?: string; name?: string; summary?: string; displayName?: string; headline?: string };
type Person = { id: string; version: number; email?: string; phone?: string; defaultLocale: "ar" | "en"; translations: Translation[]; links: unknown[] };
type MediaTranslation = { locale: ContentLocale; altText: string; caption?: string };
type MediaAsset = { id: string; version: number; deliveryUrl: string; width: number; height: number; translations: MediaTranslation[] };
type ProjectMedia = { assetId: string; sortOrder: number; asset: MediaAsset };
type ProjectMediaData = { coverAssetId?: string; items: ProjectMedia[] };
type Project = { id: string; version: number; slug: string; kind: string; isOngoing: boolean; repositoryUrl?: string; demoUrl?: string; coverAssetId?: string; updatedAt: string; translations: Translation[]; highlights: Highlight[]; media: ProjectMedia[] };
type ProfileSection = { sectionKey: string; webEnabled: boolean; pdfEnabled: boolean; webOrder: number; pdfOrder: number };
type PdfSetting = { version: number; locale: "ar" | "en"; templateKey: string; paperSize: string; fontSize: number; marginMm: number; targetPages: number };
type Profile = { id: string; internalName: string; slug: string; defaultLocale: "ar" | "en"; translations: Translation[]; sections: ProfileSection[]; pdfSettings: PdfSetting[] };
type Site = { id: string; name: string; slug: string; baseUrl?: string; deploymentTargetKey?: string; currentPublicationId?: string; profiles: unknown[]; locales: unknown[] };
type Preview = { locale: "ar" | "en"; direction: "rtl" | "ltr"; fullName: string; headline: string; summary: string; email?: string; phone?: string; skills: Array<{ category: string; name: string }>; projects: Array<{ name: string; summary: string; skills: string[]; highlights: string[] }> };

function PageHeader({ title, description, action }: { title: string; description: string; action?: ReactNode }) { return <header className="page-header"><div><h1>{title}</h1><p>{description}</p></div>{action}</header>; }
function LoadingState() { const { l } = useAdminI18n(); return <div className="loading-state" role="status"><div className="loading-bars"><span /><span /><span /></div><span className="sr-only">{l("جارٍ التحميل", "Loading")}</span></div>; }
function ErrorState({ error, retry }: { error: unknown; retry: () => void }) { const { l } = useAdminI18n(); const message = error instanceof ApiError ? localizeAdminError(error, l) : l("تعذر تحميل البيانات.", "Unable to load the data."); return <div className="error-state" role="alert"><div><AlertCircle size={32} aria-hidden="true" /><h2>{l("تعذر الاتصال", "Connection error")}</h2><p>{message}</p><button className="button button-secondary" onClick={retry}><RefreshCw size={17} aria-hidden="true" />{l("إعادة المحاولة", "Try again")}</button></div></div>; }

function Dashboard() {
  const navigate = useNavigate(); const { l, count } = useAdminI18n();
  const query = useQuery({ queryKey: ["dashboard"], queryFn: async () => { const [profiles, projects, sites] = await Promise.all([api<Profile[]>("/api/v1/admin/profiles"), api<Project[]>("/api/v1/admin/projects"), api<Site[]>("/api/v1/admin/sites")]); return { profiles, projects, sites }; } });
  const title = l("نظرة عامة", "Overview");
  if (query.isLoading) return <><PageHeader title={title} description={l("الحالة الحالية للمحتوى والنشر.", "Current content and publishing status.")} /><LoadingState /></>;
  if (query.isError) return <><PageHeader title={title} description={l("قد يستغرق استيقاظ الخدمة المجانية قرابة دقيقة.", "The free service may take about a minute to wake up.")} /><ErrorState error={query.error} retry={() => void query.refetch()} /></>;
  const data = query.data!; const missing = data.profiles.filter(profile => profile.translations.length < 2).length;
  const missingLabel = count(missing, { en: { one: "missing translation", other: "missing translations" }, ar: { zero: "ترجمات ناقصة", one: "ترجمة ناقصة", two: "ترجمتان ناقصتان", few: "ترجمات ناقصة", many: "ترجمة ناقصة", other: "ترجمة ناقصة" } });
  const unconfiguredSites = data.sites.filter(x => !x.deploymentTargetKey).length;
  const unconfiguredSitesLabel = count(unconfiguredSites, { en: { one: "site without hosting", other: "sites without hosting" }, ar: { zero: "مواقع مربوطة بالاستضافة", one: "موقع غير مربوط بالاستضافة", two: "موقعان غير مربوطين بالاستضافة", few: "مواقع غير مربوطة بالاستضافة", many: "موقعًا غير مربوط بالاستضافة", other: "موقع غير مربوط بالاستضافة" } });
  return <><PageHeader title={title} description={l("ابدأ بما يحتاج إجراءً، ثم راجع البروفايلات المنشورة.", "Start with what needs attention, then review your published profiles.")} action={<button className="button button-primary" onClick={() => navigate("/projects")}><Plus size={18} aria-hidden="true" />{l("إضافة محتوى", "Add content")}</button>} /><section className="action-rail"><div className="priority-block"><h2>{l("يحتاج انتباهك", "Needs your attention")}</h2><ul className="priority-list"><li className="priority-item"><span className="status-dot" /><div><b>{missingLabel}</b><div className="row-meta">{l("لا تُنشر لغة ناقصة بصمت.", "An incomplete language is never published silently.")}</div></div></li><li className="priority-item"><span className="status-dot" /><div><b>{unconfiguredSitesLabel}</b><div className="row-meta">{l("يمكن إكمال كل العمل المحلي قبل إضافة الأسرار.", "You can complete the local work before adding secrets.")}</div></div></li><li className="priority-item"><span className="status-dot" /><div><b>{l("فحص PDF مطلوب قبل أول نشر", "PDF review is required before the first publish")}</b><div className="row-meta">{l("الاستخراج والخطوط واتجاه العربية جزء من القبول.", "Text extraction, fonts, and Arabic direction are part of acceptance.")}</div></div></li></ul></div><div className="priority-block"><h2>{l("المحتوى الحالي", "Current content")}</h2><ul className="priority-list"><li className="priority-item"><FileText aria-hidden="true" /><div><b>{count(data.profiles.length, { en: { one: "profile", other: "profiles" }, ar: { zero: "بروفايلات", one: "بروفايل", two: "بروفايلان", few: "بروفايلات", many: "بروفايلًا", other: "بروفايل" } })}</b><div className="row-meta">{l("تنتقي من حقائق مشتركة", "Selects from shared facts")}</div></div></li><li className="priority-item"><FolderKanban aria-hidden="true" /><div><b>{count(data.projects.length, { en: { one: "project", other: "projects" }, ar: { zero: "مشاريع", one: "مشروع", two: "مشروعان", few: "مشاريع", many: "مشروعًا", other: "مشروع" } })}</b><div className="row-meta">{l("الخبرة الوظيفية تبقى اختيارية", "Employment experience remains optional")}</div></div></li><li className="priority-item"><Globe2 aria-hidden="true" /><div><b>{count(data.sites.length, { en: { one: "site", other: "sites" }, ar: { zero: "مواقع", one: "موقع", two: "موقعان", few: "مواقع", many: "موقعًا", other: "موقع" } })}</b><div className="row-meta">{l("لكل منها نشر مستقل", "Each has an independent publish flow")}</div></div></li></ul></div></section><section style={{ marginTop: 48 }}><h2>{l("البروفايلات", "Profiles")}</h2>{data.profiles.length ? <div className="profile-list">{data.profiles.map(profile => <div className="row" key={profile.id}><div><div className="row-title">{profile.internalName}</div><div className="row-meta"><bdi>/{profile.slug}</bdi> · {profile.translations.length}/2 {l("لغات", "languages")}</div></div><div className="row-actions"><button className="button button-secondary" onClick={() => navigate(`/resume?profile=${profile.id}`)}>{l("المعاينة", "Preview")}</button></div></div>)}</div> : <div className="empty-state"><div><FileText size={34} aria-hidden="true" /><h3>{l("لا توجد بروفايلات بعد", "No profiles yet")}</h3><p>{l("أنشئ بروفايلًا ينتقي المشاريع والمهارات المشتركة دون نسخ الحقائق.", "Create a profile that selects shared projects and skills without duplicating facts.")}</p><button className="button button-primary" onClick={() => navigate("/profiles")}><Plus size={17} aria-hidden="true" />{l("إنشاء أول بروفايل", "Create your first profile")}</button></div></div>}</section></>;
}

function OwnerPage() {
  const { l } = useAdminI18n(); const client = useQueryClient(); const query = useQuery({ queryKey: ["person"], queryFn: () => api<Person>("/api/v1/admin/person") }); const [locale, setLocale] = useState<ContentLocale>("ar");
  const mutation = useMutation({ mutationFn: (person: Person) => api<Person>("/api/v1/admin/person", { method: "PUT", body: JSON.stringify({ version: person.version, email: person.email, phone: person.phone, defaultLocale: person.defaultLocale, en: translationInput(person, "en"), ar: translationInput(person, "ar") }) }), onSuccess: value => client.setQueryData(["person"], value) });
  const [draft, setDraft] = useState<Person | null>(null); const person = draft ?? query.data ?? null;
  if (query.isLoading) return <><PageHeader title={l("بياناتي", "My details")} description={l("حقائق المالك المشتركة بين جميع البروفايلات.", "Owner facts shared by all profiles.")} /><LoadingState /></>;
  if (query.isError || !person) return <><PageHeader title={l("بياناتي", "My details")} description={l("حقائق المالك المشتركة.", "Shared owner facts.")} /><ErrorState error={query.error} retry={() => void query.refetch()} /></>;
  const tr = person.translations.find(x => x.locale === locale) ?? { locale };
  const updateTranslation = (key: keyof Translation, value: string) => setDraft({ ...person, translations: [...person.translations.filter(x => x.locale !== locale), { ...tr, [key]: value }] });
  const contentDirection = locale === "ar" ? "rtl" : "ltr";
  return <><PageHeader title={l("بياناتي", "My details")} description={l("لا تضع معلومات لا تريد نشرها؛ لكل بروفايل تحكم مستقل في ظهور التواصل.", "Only add information you are comfortable publishing; each profile controls contact visibility independently.")} action={<button className="button button-primary" disabled={!draft || mutation.isPending} onClick={() => mutation.mutate(person)}><Save size={18} aria-hidden="true" />{mutation.isPending ? l("جارٍ الحفظ", "Saving…") : l("حفظ التغييرات", "Save changes")}</button>} />{mutation.isError && <div className="notice" role="alert">{localizeAdminError(mutation.error, l)}{mutation.error instanceof ApiError && mutation.error.status === 409 ? l(" أعد تحميل أحدث نسخة قبل الدمج.", " Reload the latest version before merging.") : ""}</div>}{mutation.isSuccess && <div className="notice success-notice" aria-live="polite"><Check size={18} aria-hidden="true" />{l("تم الحفظ على الخادم.", "Saved on the server.")}</div>}<div className="tabs" role="tablist"><button className="tab" role="tab" aria-selected={locale === "ar"} onClick={() => setLocale("ar")}>العربية {hasTranslation(person, "ar") ? "" : l("— ناقصة", "— missing")}</button><button className="tab" role="tab" aria-selected={locale === "en"} onClick={() => setLocale("en")}>English {hasTranslation(person, "en") ? "" : l("— ناقصة", "— missing")}</button></div><section className="editor-panel" lang={locale} dir={contentDirection}><div className="form-grid"><div className="field"><label htmlFor="fullName">{l("الاسم الكامل", "Full name")}</label><input id="fullName" dir={contentDirection} value={tr.fullName ?? ""} onChange={event => updateTranslation("fullName", event.target.value)} /></div><div className="field"><label htmlFor="headline">{l("المسمى الأساسي", "Primary headline")}</label><input id="headline" dir={contentDirection} value={tr.defaultHeadline ?? ""} onChange={event => updateTranslation("defaultHeadline", event.target.value)} /></div><div className="field span-2"><label htmlFor="summary">{l("الملخص", "Summary")}</label><textarea id="summary" dir={contentDirection} value={tr.defaultSummary ?? ""} onChange={event => updateTranslation("defaultSummary", event.target.value)} /></div><div className="field"><label htmlFor="email">{l("البريد", "Email")}</label><input id="email" dir="ltr" type="email" value={person.email ?? ""} onChange={event => setDraft({ ...person, email: event.target.value })} /></div><div className="field"><label htmlFor="phone">{l("الهاتف", "Phone")}</label><input id="phone" dir="ltr" type="tel" value={person.phone ?? ""} onChange={event => setDraft({ ...person, phone: event.target.value })} /></div></div></section></>;
}

function projectKindLabel(kind: string, l: (ar: string, en: string) => string) {
  const labels: Record<string, [string, string]> = {
    personal: ["مشروع شخصي", "Personal project"],
    openSource: ["مفتوح المصدر", "Open source"],
    freelance: ["عمل حر", "Freelance work"],
    employment: ["ضمن وظيفة", "Employment"]
  };
  return labels[kind] ? l(...labels[kind]) : kind;
}

function ProjectsPage() {
  const { l } = useAdminI18n(); const client = useQueryClient(); const [editing, setEditing] = useState<Project | "new" | null>(null); const query = useQuery({ queryKey: ["projects"], queryFn: () => api<Project[]>("/api/v1/admin/projects") });
  const refresh = () => { void client.invalidateQueries({ queryKey: ["projects"] }); void client.invalidateQueries({ queryKey: ["dashboard"] }); };
  const save = useMutation({ mutationFn: ({ project, body }: { project?: Project; body: unknown }) => api<Project>(project ? `/api/v1/admin/projects/${project.id}` : "/api/v1/admin/projects", { method: project ? "PUT" : "POST", body: JSON.stringify(body) }), onSuccess: () => { setEditing(null); refresh(); } });
  const archive = useMutation({ mutationFn: (id: string) => api<void>(`/api/v1/admin/projects/${id}`, { method: "DELETE" }), onSuccess: refresh });
  return <><PageHeader title={l("المشاريع", "Projects")} description={l("مشاريع شخصية أو مفتوحة المصدر أو عمل فعلي؛ لا تُحوّل المشروع الشخصي إلى خبرة وظيفية.", "Personal, open-source, or real-work projects; do not turn a personal project into employment experience.")} action={<button className="button button-primary" onClick={() => setEditing("new")}><Plus size={18} aria-hidden="true" />{l("إضافة مشروع", "Add project")}</button>} />{editing && <ProjectCreateForm project={editing === "new" ? undefined : editing} pending={save.isPending} error={save.error} cancel={() => setEditing(null)} submit={value => save.mutate({ project: editing === "new" ? undefined : editing, body: value })} />}{archive.isError && <div className="notice" role="alert">{localizeAdminError(archive.error, l)}</div>}{query.isLoading ? <LoadingState /> : query.isError ? <ErrorState error={query.error} retry={() => void query.refetch()} /> : query.data?.length ? <div className="profile-list">{query.data.map(project => { const ar = project.translations.find(x => x.locale === "ar"); const en = project.translations.find(x => x.locale === "en"); return <article className="row" key={project.id}><div><div className="row-title">{ar?.name || en?.name || project.slug}</div><div className="row-meta"><bdi>{project.slug}</bdi> · {projectKindLabel(project.kind, l)} · {project.isOngoing ? l("مستمر", "Ongoing") : l("مكتمل", "Completed")}</div><p>{ar?.summary || en?.summary}</p></div><div className="row-actions"><button className="button button-secondary" onClick={() => setEditing(project)}>{l("تعديل", "Edit")}</button><button className="button button-danger" disabled={archive.isPending} onClick={() => { if (window.confirm(l("أرشفة هذا المشروع؟ سيختفي من القوائم العامة بعد النشر التالي.", "Archive this project? It will disappear from public lists after the next publish."))) archive.mutate(project.id); }}>{l("أرشفة", "Archive")}</button></div></article>; })}</div> : <div className="empty-state"><div><FolderKanban size={36} aria-hidden="true" /><h2>{l("أضف مشروعك الأول", "Add your first project")}</h2><p>{l("يمكنك البدء بلا صورة، وإضافة وصف عربي وإنجليزي حقيقيين.", "You can start without an image and add genuine Arabic and English descriptions.")}</p><button className="button button-primary" onClick={() => setEditing("new")}><Plus size={18} aria-hidden="true" />{l("إضافة مشروع", "Add project")}</button></div></div>}</>;
}

function ProjectCreateForm({ project, pending, error, cancel, submit }: { project?: Project; pending: boolean; error: Error | null; cancel: () => void; submit: (value: unknown) => void }) {
  const { l } = useAdminI18n();
  const ar = project?.translations.find(x => x.locale === "ar"), en = project?.translations.find(x => x.locale === "en");
  const [value, setValue] = useState({ slug: project?.slug ?? "", kind: project?.kind ?? "personal", nameAr: ar?.name ?? "", nameEn: en?.name ?? "", summaryAr: ar?.summary ?? "", summaryEn: en?.summary ?? "", repositoryUrl: project?.repositoryUrl ?? "", demoUrl: project?.demoUrl ?? "", isOngoing: project?.isOngoing ?? true });
  return <section className="editor-panel" style={{ marginBottom: 28 }} aria-labelledby="project-editor"><div className="toolbar"><h2 id="project-editor">{project ? l("تعديل المشروع", "Edit project") : l("مشروع جديد", "New project")}</h2><button className="icon-button" onClick={cancel} aria-label={l("إغلاق", "Close")}><X aria-hidden="true" /></button></div>{error && <div className="notice" role="alert">{localizeAdminError(error, l)}</div>}<div className="form-grid"><div className="field"><label htmlFor="slug">{l("المسار اللاتيني", "Latin slug")}</label><input id="slug" dir="ltr" value={value.slug} onChange={event => setValue({ ...value, slug: event.target.value })} placeholder="my-project" /></div><div className="field"><label htmlFor="kind">{l("النوع", "Type")}</label><select id="kind" value={value.kind} onChange={event => setValue({ ...value, kind: event.target.value })}><option value="personal">{l("مشروع شخصي", "Personal project")}</option><option value="openSource">{l("مفتوح المصدر", "Open source")}</option><option value="freelance">{l("عمل حر", "Freelance work")}</option><option value="employment">{l("ضمن وظيفة", "Employment")}</option></select></div><div className="field"><label htmlFor="nameAr">{l("الاسم بالعربية", "Arabic name")}</label><input id="nameAr" dir="rtl" value={value.nameAr} onChange={event => setValue({ ...value, nameAr: event.target.value })} /></div><div className="field"><label htmlFor="nameEn">{l("الاسم بالإنجليزية", "English name")}</label><input id="nameEn" dir="ltr" value={value.nameEn} onChange={event => setValue({ ...value, nameEn: event.target.value })} /></div><div className="field"><label htmlFor="summaryAr">{l("الملخص بالعربية", "Arabic summary")}</label><textarea id="summaryAr" dir="rtl" value={value.summaryAr} onChange={event => setValue({ ...value, summaryAr: event.target.value })} /></div><div className="field"><label htmlFor="summaryEn">{l("الملخص بالإنجليزية", "English summary")}</label><textarea id="summaryEn" dir="ltr" value={value.summaryEn} onChange={event => setValue({ ...value, summaryEn: event.target.value })} /></div><div className="field"><label htmlFor="repositoryUrl">{l("رابط المستودع (اختياري)", "Repository URL (optional)")}</label><input id="repositoryUrl" dir="ltr" value={value.repositoryUrl} onChange={event => setValue({ ...value, repositoryUrl: event.target.value })} /></div><div className="field"><label htmlFor="demoUrl">{l("رابط المعاينة (اختياري)", "Demo URL (optional)")}</label><input id="demoUrl" dir="ltr" value={value.demoUrl} onChange={event => setValue({ ...value, demoUrl: event.target.value })} /></div><label className="checkbox-row"><input type="checkbox" checked={value.isOngoing} onChange={event => setValue({ ...value, isOngoing: event.target.checked })} />{l("المشروع مستمر", "Project is ongoing")}</label></div><div className="toolbar-actions"><button className="button button-primary" disabled={pending} onClick={() => submit({ version: project?.version ?? 0, slug: value.slug, kind: value.kind, isOngoing: value.isOngoing, repositoryUrl: value.repositoryUrl || null, demoUrl: value.demoUrl || null, en: { name: value.nameEn, summary: value.summaryEn }, ar: { name: value.nameAr, summary: value.summaryAr } })}><Save size={18} aria-hidden="true" />{l("حفظ المشروع", "Save project")}</button><button className="button button-secondary" onClick={cancel}>{l("إلغاء", "Cancel")}</button></div>{project && <><HighlightEditor basePath={`/api/v1/admin/projects/${project.id}/highlights`} highlights={project.highlights} queryKey={["projects"]} /><ProjectMediaEditor project={project} /></>}</section>;
}

function ProjectMediaEditor({ project }: { project: Project }) {
  const { l } = useAdminI18n();
  const query = useQuery({ queryKey: ["project-media", project.id], queryFn: () => api<ProjectMediaData>(`/api/v1/admin/projects/${project.id}/media`) });
  if (query.isLoading) return <LoadingState />; if (query.isError || !query.data) return <div className="notice" role="alert">{l("تعذر تحميل صور المشروع.", "Unable to load project images.")}</div>;
  return <ProjectMediaForm key={JSON.stringify(query.data)} project={project} initial={query.data.items} initialCover={query.data.coverAssetId} refetch={() => void query.refetch()} />;
}
function ProjectMediaForm({ project, initial, initialCover, refetch }: { project: Project; initial: ProjectMedia[]; initialCover?: string; refetch: () => void }) {
  const { l } = useAdminI18n();
  const [items, setItems] = useState(initial); const [file, setFile] = useState<File | null>(null); const [altAr, setAltAr] = useState(""); const [altEn, setAltEn] = useState(""); const [cover, setCover] = useState(initialCover ?? initial[0]?.assetId ?? "");
  const persist = (next: ProjectMedia[], coverId = cover) => api<void>(`/api/v1/admin/projects/${project.id}/media`, { method: "PUT", body: JSON.stringify({ coverAssetId: coverId || null, assetIds: next.map(item => item.assetId) }) });
  const save = useMutation({ mutationFn: async () => { for (const item of items) { const ar = item.asset.translations.find(x => x.locale === "ar"), en = item.asset.translations.find(x => x.locale === "en"); await api(`/api/v1/admin/media/${item.asset.id}`, { method: "PUT", body: JSON.stringify({ version: item.asset.version, altAr: ar?.altText ?? "", altEn: en?.altText ?? "", captionAr: ar?.caption ?? null, captionEn: en?.caption ?? null }) }); } await persist(items); }, onSuccess: refetch });
  const upload = useMutation({ mutationFn: async () => { if (!file) throw new Error(l("اختر صورة.", "Choose an image.")); const form = new FormData(); form.append("file", file); form.append("altAr", altAr); form.append("altEn", altEn); const asset = await uploadApiFile<MediaAsset>("/api/v1/admin/media", form); const next = [...items, { assetId: asset.id, sortOrder: items.length, asset }]; const nextCover = cover || asset.id; await persist(next, nextCover); return next; }, onSuccess: () => { setFile(null); setAltAr(""); setAltEn(""); refetch(); } });
  const move = (index: number, delta: number) => { const target = index + delta; if (target < 0 || target >= items.length) return; const next = [...items]; [next[index], next[target]] = [next[target], next[index]]; setItems(next.map((item, sortOrder) => ({ ...item, sortOrder }))); };
  const translation = (item: ProjectMedia, locale: ContentLocale) => item.asset.translations.find(x => x.locale === locale) ?? { locale, altText: "", caption: "" };
  const updateTranslation = (assetId: string, locale: ContentLocale, key: "altText" | "caption", value: string) => setItems(current => current.map(item => item.assetId !== assetId ? item : { ...item, asset: { ...item.asset, translations: [...item.asset.translations.filter(x => x.locale !== locale), { ...translation(item, locale), [key]: value }] } }));
  return <section className="nested-editor"><h3>{l("صور المشروع", "Project images")}</h3><p className="field-help">{l("هذه الصور مخصصة للنشر العام. PNG/JPEG/WebP فقط، حتى 5 MB و6000×6000، مع وصف بديل باللغتين.", "These images are for public publishing. PNG/JPEG/WebP only, up to 5 MB and 6000×6000, with alt text in both languages.")}</p>{items.map((item, index) => <article className="media-editor-row" key={item.assetId}><img src={item.asset.deliveryUrl} width="120" height="90" alt="" /><div className="form-grid"><div className="field"><label htmlFor={`media-ar-${item.assetId}`}>{l("الوصف البديل بالعربية", "Arabic alt text")}</label><input id={`media-ar-${item.assetId}`} dir="rtl" value={translation(item, "ar").altText} onChange={event => updateTranslation(item.assetId, "ar", "altText", event.target.value)} /></div><div className="field"><label htmlFor={`media-en-${item.assetId}`}>{l("الوصف البديل بالإنجليزية", "English alt text")}</label><input id={`media-en-${item.assetId}`} dir="ltr" value={translation(item, "en").altText} onChange={event => updateTranslation(item.assetId, "en", "altText", event.target.value)} /></div><label className="checkbox-row"><input type="radio" name={`cover-${project.id}`} checked={cover === item.assetId} onChange={() => setCover(item.assetId)} />{l("صورة الغلاف", "Cover image")}</label></div><div className="row-actions"><button className="icon-button" disabled={index === 0} onClick={() => move(index, -1)} aria-label={l("نقل الصورة لأعلى", "Move image up")}><ChevronUp /></button><button className="icon-button" disabled={index === items.length - 1} onClick={() => move(index, 1)} aria-label={l("نقل الصورة لأسفل", "Move image down")}><ChevronDown /></button><button className="icon-button danger-icon" onClick={() => { const next = items.filter(x => x.assetId !== item.assetId); setItems(next); if (cover === item.assetId) setCover(next[0]?.assetId ?? ""); }} aria-label={l("فصل الصورة", "Detach image")}><Trash2 /></button></div></article>)}<div className="media-upload"><div className="field"><label htmlFor={`media-file-${project.id}`}>{l("صورة جديدة", "New image")}</label><input id={`media-file-${project.id}`} type="file" accept="image/png,image/jpeg,image/webp" onChange={event => setFile(event.target.files?.[0] ?? null)} /></div><div className="form-grid"><div className="field"><label htmlFor={`upload-alt-ar-${project.id}`}>{l("الوصف البديل بالعربية", "Arabic alt text")}</label><input id={`upload-alt-ar-${project.id}`} dir="rtl" value={altAr} onChange={event => setAltAr(event.target.value)} /></div><div className="field"><label htmlFor={`upload-alt-en-${project.id}`}>{l("الوصف البديل بالإنجليزية", "English alt text")}</label><input id={`upload-alt-en-${project.id}`} dir="ltr" value={altEn} onChange={event => setAltEn(event.target.value)} /></div></div>{upload.isError && <div className="notice" role="alert">{upload.error instanceof ApiError && upload.error.code === "MEDIA_STORAGE_NOT_CONFIGURED" ? l("رفع الصور غير مهيأ بعد؛ أضف إعدادات تخزين الصور للخادم.", "Image uploads are not configured yet; add the server image-storage settings.") : localizeAdminError(upload.error, l)}</div>}<button className="button button-secondary" disabled={!file || !altAr || !altEn || upload.isPending} onClick={() => upload.mutate()}><Upload size={17} />{l("رفع وربط الصورة", "Upload and attach image")}</button></div>{save.isError && <div className="notice" role="alert">{localizeAdminError(save.error, l)}</div>}<button className="button button-secondary" disabled={save.isPending} onClick={() => save.mutate()}><Save size={17} />{l("حفظ الترتيب والأوصاف", "Save order and alt text")}</button></section>;
}

function ContentPage() { return <ContentManager />; }

function ProfilesPage() {
  const { l } = useAdminI18n(); const client = useQueryClient(); const query = useQuery({ queryKey: ["profiles"], queryFn: () => api<Profile[]>("/api/v1/admin/profiles") }); const [show, setShow] = useState(false);
  const create = useMutation({ mutationFn: (body: unknown) => api<Profile>("/api/v1/admin/profiles", { method: "POST", body: JSON.stringify(body) }), onSuccess: () => { setShow(false); void client.invalidateQueries({ queryKey: ["profiles"] }); } });
  const duplicate = useMutation({ mutationFn: ({ id, internalName, slug }: { id: string; internalName: string; slug: string }) => api<Profile>(`/api/v1/admin/profiles/${id}/duplicate`, { method: "POST", body: JSON.stringify({ internalName, slug }) }), onSuccess: () => void client.invalidateQueries({ queryKey: ["profiles"] }) });
  const [name, setName] = useState(""), [slug, setSlug] = useState("");
  return <><PageHeader title={l("البروفايلات", "Profiles")} description={l("كل بروفايل يغيّر الانتقاء والترتيب والتركيز دون تكرار الحقائق المشتركة.", "Each profile changes selection, order, and emphasis without duplicating shared facts.")} action={<button className="button button-primary" onClick={() => setShow(true)}><Plus size={18} aria-hidden="true" />{l("بروفايل جديد", "New profile")}</button>} />{show && <section className="editor-panel" style={{ marginBottom: 28 }}><h2>{l("بروفايل جديد", "New profile")}</h2>{create.isError && <div className="notice">{localizeAdminError(create.error, l)}</div>}<div className="form-grid"><div className="field"><label htmlFor="profileName">{l("الاسم الداخلي", "Internal name")}</label><input id="profileName" value={name} onChange={event => setName(event.target.value)} /></div><div className="field"><label htmlFor="profileSlug">{l("المسار", "Slug")}</label><input id="profileSlug" dir="ltr" value={slug} onChange={event => setSlug(event.target.value)} /></div></div><button className="button button-primary" disabled={create.isPending} onClick={() => create.mutate({ internalName: name, slug, defaultLocale: "en", headlineEn: "Software Engineer | Flutter & .NET Backend", summaryEn: "", headlineAr: "مهندس برمجيات | Flutter وخدمات خلفية باستخدام .NET", summaryAr: "" })}>{l("إنشاء كمسودة", "Create draft")}</button></section>}{duplicate.isError && <div className="notice" role="alert">{localizeAdminError(duplicate.error, l)}</div>}{query.isLoading ? <LoadingState /> : query.isError ? <ErrorState error={query.error} retry={() => void query.refetch()} /> : query.data?.length ? <div className="profile-list">{query.data.map(profile => <div className="row" key={profile.id}><div><div className="row-title">{profile.internalName}</div><div className="row-meta"><bdi>/{profile.slug}</bdi> · {profile.translations.length === 2 ? l("اللغتان موجودتان", "Both languages complete") : l("ترجمة ناقصة", "Translation missing")}</div></div><div className="row-actions"><NavLink className="button button-secondary" to={`/resume?profile=${profile.id}`}>{l("تحرير ومعاينة", "Edit & preview")}</NavLink><button className="button button-secondary" disabled={duplicate.isPending} onClick={() => { const nextSlug = window.prompt(l("مسار النسخة الجديدة", "New copy slug"), `${profile.slug}-copy`); if (!nextSlug) return; const nextName = window.prompt(l("الاسم الداخلي للنسخة", "Internal name for the copy"), `${profile.internalName} — ${l("نسخة", "copy")}`); if (nextName) duplicate.mutate({ id: profile.id, internalName: nextName, slug: nextSlug }); }}>{l("نسخ", "Duplicate")}</button></div></div>)}</div> : <div className="empty-state"><div><FileText size={36} aria-hidden="true" /><h2>{l("لا توجد بروفايلات", "No profiles")}</h2><p>{l("أنشئ بروفايل Flutter وآخر Flutter + .NET من نفس المشاريع والمهارات.", "Create a Flutter profile and a Flutter + .NET profile from the same projects and skills.")}</p></div></div>}</>;
}

function ResumeEditor() {
  const { l } = useAdminI18n(); const location = useLocation(); const [locale, setLocale] = useState<ContentLocale>("ar"); const [mobileView, setMobileView] = useState<"edit" | "preview">("edit");
  const profiles = useQuery({ queryKey: ["profiles"], queryFn: () => api<Profile[]>("/api/v1/admin/profiles") });
  const requested = new URLSearchParams(location.search).get("profile"); const profileId = requested ?? profiles.data?.[0]?.id; const profile = profiles.data?.find(x => x.id === profileId);
  const preview = useQuery({ queryKey: ["preview", profileId, locale], enabled: !!profileId, queryFn: () => api<Preview>(`/api/v1/admin/profiles/${profileId}/preview?locale=${locale}&target=pdf`) });
  return <><PageHeader title={l("محرر السيرة", "Resume editor")} description={l("المعاينة فورية؛ زر تنزيل PDF يبني نسخة جديدة مباشرة من بيانات قاعدة البيانات الحالية.", "The preview is live; downloading a PDF builds a fresh copy from the current database data.")} action={profile && <CurrentPdfDownload profile={profile} locale={locale} />} /><div className="notice">{l("المعاينة ليست ملف PDF نهائيًا. النسخة المباشرة تستخدم قالب Senior Mobile Engineer، بينما التصدير المنشور يمر بفحوص", "This preview is not the final PDF. The direct download uses the Senior Mobile Engineer template, while published exports run")}{" "}<bdi>pdftotext / pdffonts / pdfinfo</bdi>{l(".", ".")}</div>{profile && <PrivatePdfExports profile={profile} locale={locale} />}<div className="tabs"><button className="tab" aria-selected={locale === "ar"} onClick={() => setLocale("ar")}>العربية</button><button className="tab" aria-selected={locale === "en"} onClick={() => setLocale("en")}>English</button></div><div className="mobile-tabs tabs"><button className="tab" aria-selected={mobileView === "edit"} onClick={() => setMobileView("edit")}>{l("تحرير", "Edit")}</button><button className="tab" aria-selected={mobileView === "preview"} onClick={() => setMobileView("preview")}>{l("معاينة", "Preview")}</button></div><div className="editor-layout"><section className={`editor-panel editor-form ${mobileView === "preview" ? "mobile-hidden" : ""}`}>{profile ? <ProfileSettings key={`${profile.id}-${locale}`} profile={profile} locale={locale} saved={() => { void profiles.refetch(); void preview.refetch(); }} /> : <LoadingState />}</section><section className={`editor-preview ${mobileView === "preview" ? "mobile-active" : ""}`}><div className="toolbar"><h2>{l("معاينة القالب", "Template preview")}</h2><span className="status status-warning">{l("معاينة HTML", "HTML preview")}</span></div>{preview.isLoading ? <LoadingState /> : preview.isError ? <ErrorState error={preview.error} retry={() => void preview.refetch()} /> : preview.data ? <ResumePaper value={preview.data} /> : <div className="empty-state">{l("اختر بروفايلًا للمعاينة.", "Choose a profile to preview.")}</div>}</section></div></>;
}

function CurrentPdfDownload({ profile, locale }: { profile: Profile; locale: ContentLocale }) {
  const { l } = useAdminI18n();
  const [downloading, setDownloading] = useState(false); const [error, setError] = useState("");
  const download = async () => {
    setError(""); setDownloading(true);
    try {
      const blob = await downloadApiFile(`/api/v1/admin/profiles/${profile.id}/pdf?locale=${locale}`);
      const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `resume-${locale}.pdf`; link.click(); URL.revokeObjectURL(url);
    } catch (value) { setError(value instanceof ApiError ? localizeAdminError(value, l) : l("تعذر بناء ملف PDF.", "Unable to build the PDF.")); } finally { setDownloading(false); }
  };
  return <div><button className="button button-primary" disabled={downloading} onClick={() => void download()}><Download size={18} aria-hidden="true" />{downloading ? l("جارٍ البناء…", "Building…") : l("تنزيل PDF الحالي", "Download current PDF")}</button>{error && <div className="notice" role="alert">{error}</div>}</div>;
}

type PrivateExport = { id: string; revision: number; state: string; requestedAt: string; completedAt?: string; errorSummary?: string; artifacts: Array<{ id: string; locale: ContentLocale; sizeBytes: number; pageCount?: number; createdAt: string }> };
function privateExportStateLabel(state: string, l: (ar: string, en: string) => string) {
  const labels: Record<string, [string, string]> = { queued: ["في الانتظار", "Queued"], running: ["جارٍ التنفيذ", "Running"], building: ["جارٍ البناء", "Building"], validating: ["جارٍ التحقق", "Validating"], deploying: ["جارٍ النشر", "Deploying"], succeeded: ["ناجح", "Succeeded"], failed: ["فشل", "Failed"], cancelled: ["أُلغي", "Cancelled"] };
  return labels[state] ? l(...labels[state]) : l("حالة غير معروفة", "Unknown state");
}
function PrivatePdfExports({ profile, locale }: { profile: Profile; locale: ContentLocale }) {
  const { l, count } = useAdminI18n(); const client = useQueryClient(); const [downloading, setDownloading] = useState<string | null>(null); const [downloadError, setDownloadError] = useState("");
  const history = useQuery({ queryKey: ["private-pdf-exports", profile.id], queryFn: () => api<PrivateExport[]>(`/api/v1/admin/profiles/${profile.id}/pdf-exports`) });
  const create = useMutation({ mutationFn: (locales: ContentLocale[]) => api<{ publicationId: string }>(`/api/v1/admin/profiles/${profile.id}/pdf-exports`, { method: "POST", body: JSON.stringify({ locales, idempotencyKey: crypto.randomUUID() }) }), onSuccess: () => void client.invalidateQueries({ queryKey: ["private-pdf-exports", profile.id] }) });
  const download = async (publicationId: string, artifact: PrivateExport["artifacts"][number]) => { setDownloadError(""); setDownloading(artifact.id); try { const blob = await downloadApiFile(`/api/v1/admin/publications/${publicationId}/artifacts/${artifact.id}/download`); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `resume-${artifact.locale}.pdf`; link.click(); URL.revokeObjectURL(url); } catch (error) { setDownloadError(error instanceof ApiError ? localizeAdminError(error, l) : l("تعذر تنزيل الملف الخاص.", "Unable to download the private file.")); } finally { setDownloading(null); } };
  return <section className="private-export-panel"><div><h2>{l("تصدير PDF خاص", "Private PDF export")}</h2><p className="field-help">{l("يُبنى في مستودع عمليات خاص، ويُحفظ 7 أيام فقط، ولا يدخل ملفات الموقع العام.", "Built in a private operations repository, retained for 7 days, and excluded from public site files.")}</p></div><div className="row-actions"><button className="button button-secondary" disabled={create.isPending} onClick={() => create.mutate([locale])}>{l("توليد", "Generate")} {locale === "ar" ? "العربية" : "English"}</button><button className="button button-secondary" disabled={create.isPending} onClick={() => create.mutate(["ar", "en"])}>{l("توليد اللغتين", "Generate both languages")}</button></div>{create.isError && <div className="notice" role="alert">{localizeAdminError(create.error, l)}</div>}{history.data?.some(item => item.artifacts.length > 0) && <div className="publication-history">{history.data.filter(item => item.artifacts.length > 0).slice(0, 3).map(item => <div className="publication-row" key={item.id}><div><b>{l("تصدير", "Export")} {item.revision}</b><div className="row-meta">{privateExportStateLabel(item.state, l)} · {new Date(item.requestedAt).toLocaleDateString(locale)}</div></div><div className="row-actions">{item.artifacts.map(artifact => <button key={artifact.id} className="button button-secondary" disabled={downloading === artifact.id} onClick={() => void download(item.id, artifact)}><Download size={16} />{artifact.locale.toUpperCase()} · {artifact.pageCount == null ? l("عدد الصفحات غير متاح", "Page count unavailable") : count(artifact.pageCount, { en: { one: "page", other: "pages" }, ar: { zero: "صفحات", one: "صفحة", two: "صفحتان", few: "صفحات", many: "صفحة", other: "صفحة" } })}</button>)}</div></div>)}</div>}{downloadError && <div className="notice" role="alert">{downloadError}</div>}</section>;
}

const sectionLabels: Record<string, [string, string]> = { summary: ["الملخص المهني", "Professional summary"], skills: ["المهارات التقنية", "Technical skills"], projects: ["المشاريع", "Projects"], experience: ["الخبرة العملية", "Work experience"], education: ["التعليم", "Education"], certifications: ["الشهادات", "Certifications"], languages: ["اللغات", "Languages"] };
function ProfileSettings({ profile, locale, saved }: { profile: Profile; locale: ContentLocale; saved: () => void }) {
  const { l } = useAdminI18n();
  const initialSections = Object.keys(sectionLabels).map((sectionKey, index) => profile.sections.find(x => x.sectionKey === sectionKey) ?? { sectionKey, webEnabled: index < 3, pdfEnabled: index < 3, webOrder: index, pdfOrder: index }).sort((a, b) => a.pdfOrder - b.pdfOrder);
  const current = profile.pdfSettings.find(x => x.locale === locale) ?? { version: 0, locale, templateKey: "senior-mobile-engineer-v1", paperSize: "Letter", fontSize: 9.5, marginMm: 16.5, targetPages: 2 };
  const [sections, setSections] = useState(initialSections); const [pdf, setPdf] = useState(current);
  const mutation = useMutation({ mutationFn: async () => { await api<void>(`/api/v1/admin/profiles/${profile.id}/sections`, { method: "PUT", body: JSON.stringify(sections.map((x, index) => ({ ...x, webOrder: index, pdfOrder: index }))) }); return api<PdfSetting>(`/api/v1/admin/profiles/${profile.id}/pdf/${locale}`, { method: "PUT", body: JSON.stringify(pdf) }); }, onSuccess: saved });
  const move = (index: number, delta: number) => { const nextIndex = index + delta; if (nextIndex < 0 || nextIndex >= sections.length) return; const next = [...sections]; [next[index], next[nextIndex]] = [next[nextIndex], next[index]]; setSections(next); };
  return <><div className="toolbar"><h2>{l("إعدادات القالب", "Template settings")}</h2><span className={`status ${mutation.isSuccess ? "status-success" : "status-warning"}`}>{mutation.isSuccess ? l("محفوظ", "Saved") : l("مسودة", "Draft")}</span></div>{mutation.isError && <div className="notice" role="alert">{localizeAdminError(mutation.error, l)}</div>}<div className="field"><label htmlFor="profileSelect">{l("البروفايل", "Profile")}</label><select id="profileSelect" value={profile.id} disabled><option>{profile.internalName}</option></select></div><div className="form-grid"><div className="field"><label htmlFor="paperSize">{l("حجم الورق", "Paper size")}</label><select id="paperSize" value={pdf.paperSize} onChange={event => setPdf({ ...pdf, paperSize: event.target.value })}><option>A4</option><option>Letter</option></select></div><div className="field"><label htmlFor="fontSize">{l("حجم الخط", "Font size")}</label><input id="fontSize" type="number" min="9.5" max="12" step="0.5" value={pdf.fontSize} onChange={event => setPdf({ ...pdf, fontSize: Number(event.target.value) })} /></div></div><h3>{l("ترتيب الأقسام وظهورها", "Section order and visibility")}</h3>{sections.map((item, index) => <div className="row" key={item.sectionKey}><div><div className="row-title">{l(...sectionLabels[item.sectionKey])}</div><label className="checkbox-row"><input type="checkbox" checked={item.webEnabled} onChange={event => setSections(sections.map(x => x.sectionKey === item.sectionKey ? { ...x, webEnabled: event.target.checked } : x))} />{l("الموقع", "Website")}</label><label className="checkbox-row"><input type="checkbox" checked={item.pdfEnabled} onChange={event => setSections(sections.map(x => x.sectionKey === item.sectionKey ? { ...x, pdfEnabled: event.target.checked } : x))} />PDF</label></div><div className="row-actions"><button className="icon-button" disabled={index === 0} onClick={() => move(index, -1)} aria-label={`${l("رفع", "Move")} ${l(...sectionLabels[item.sectionKey])}`}><ChevronUp aria-hidden="true" /></button><button className="icon-button" disabled={index === sections.length - 1} onClick={() => move(index, 1)} aria-label={`${l("خفض", "Move")} ${l(...sectionLabels[item.sectionKey])}`}><ChevronDown aria-hidden="true" /></button></div></div>)}<button className="button button-primary" disabled={mutation.isPending} onClick={() => mutation.mutate()}><Save size={18} aria-hidden="true" />{l("حفظ إعدادات السيرة", "Save resume settings")}</button><ProfileSelectionEditor profileId={profile.id} locale={locale} /><ProfileContactEditor profileId={profile.id} /></>;
}

type HighlightSelection = { id: string; labelAr: string; labelEn: string; selected: boolean; webEnabled: boolean; pdfEnabled: boolean; sortOrder: number };
type SelectionItem = { id: string; labelAr: string; labelEn: string; selected: boolean; webEnabled: boolean; pdfEnabled: boolean; webOrder: number; pdfOrder: number; summaryOverrideAr?: string; summaryOverrideEn?: string; highlights?: HighlightSelection[] };
type ProfileSelection = { projects: SelectionItem[]; skills: SelectionItem[]; experiences: SelectionItem[]; educations: SelectionItem[]; certifications: SelectionItem[]; languages: SelectionItem[] };
const selectionLabels: Record<keyof ProfileSelection, [string, string]> = { projects: ["المشاريع", "Projects"], skills: ["المهارات", "Skills"], experiences: ["الخبرات", "Experience"], educations: ["التعليم", "Education"], certifications: ["الشهادات", "Certifications"], languages: ["اللغات", "Languages"] };
function ProfileSelectionEditor({ profileId, locale }: { profileId: string; locale: ContentLocale }) {
  const { l } = useAdminI18n();
  const query = useQuery({ queryKey: ["profile-selection", profileId], queryFn: () => api<ProfileSelection>(`/api/v1/admin/profiles/${profileId}/selection`) });
  if (query.isLoading) return <LoadingState />; if (query.isError || !query.data) return <div className="notice" role="alert">{l("تعذر تحميل انتقاء المحتوى.", "Unable to load content selection.")}</div>;
  return <SelectionForm key={`${profileId}-${JSON.stringify(query.data)}`} profileId={profileId} locale={locale} initial={query.data} />;
}
function SelectionForm({ profileId, locale, initial }: { profileId: string; locale: ContentLocale; initial: ProfileSelection }) {
  const { l } = useAdminI18n(); const [value, setValue] = useState(initial); const keys = Object.keys(selectionLabels) as Array<keyof ProfileSelection>;
  const selectedPayload = (items: SelectionItem[], includeProjectOverrides = false) => items.filter(x => x.selected).map((x, index) => ({ id: x.id, webEnabled: x.webEnabled, pdfEnabled: x.pdfEnabled, webOrder: index, pdfOrder: index, ...(includeProjectOverrides ? { summaryOverrideAr: x.summaryOverrideAr || null, summaryOverrideEn: x.summaryOverrideEn || null } : {}), ...((includeProjectOverrides || x.highlights) ? { highlights: (x.highlights ?? []).filter(h => h.selected).map((h, highlightIndex) => ({ id: h.id, webEnabled: h.webEnabled, pdfEnabled: h.pdfEnabled, sortOrder: highlightIndex })) } : {}) }));
  const mutation = useMutation({ mutationFn: async () => { await api<void>(`/api/v1/admin/profiles/${profileId}/selection`, { method: "PUT", body: JSON.stringify({ projects: selectedPayload(value.projects, true), skills: selectedPayload(value.skills) }) }); return api<void>(`/api/v1/admin/profiles/${profileId}/selection/supporting`, { method: "PUT", body: JSON.stringify({ experiences: selectedPayload(value.experiences), educations: selectedPayload(value.educations), certifications: selectedPayload(value.certifications), languages: selectedPayload(value.languages) }) }); } });
  const update = (key: keyof ProfileSelection, id: string, patch: Partial<SelectionItem>) => setValue(current => ({ ...current, [key]: current[key].map(item => item.id === id ? { ...item, ...patch } : item) }));
  const updateHighlight = (key: "projects" | "experiences", itemId: string, highlightId: string, patch: Partial<HighlightSelection>) => setValue(current => ({ ...current, [key]: current[key].map(item => item.id === itemId ? { ...item, highlights: item.highlights?.map(highlight => highlight.id === highlightId ? { ...highlight, ...patch } : highlight) } : item) }));
  const move = (key: keyof ProfileSelection, index: number, delta: number) => { const items = [...value[key]], next = index + delta; if (next < 0 || next >= items.length) return; [items[index], items[next]] = [items[next], items[index]]; setValue({ ...value, [key]: items }); };
  return <section style={{ marginTop: 28 }}><h3>{l("انتقاء المحتوى وترتيبه", "Select and order content")}</h3><p className="field-help">{l("الحقائق مشتركة؛ هذا البروفايل يحفظ اختياراته للموقع وPDF بصورة مستقلة.", "Facts are shared; this profile stores independent selections for the website and PDF.")}</p>{keys.map(key => <div key={key} style={{ marginBlock: 20 }}><div className="row-title">{l(...selectionLabels[key])}</div>{value[key].length ? value[key].map((item, index) => <div className="row" key={item.id}><div><label className="checkbox-row"><input type="checkbox" checked={item.selected} onChange={event => update(key, item.id, { selected: event.target.checked, webEnabled: event.target.checked, pdfEnabled: event.target.checked })} />{locale === "ar" ? item.labelAr : item.labelEn}</label>{item.selected && <><label className="checkbox-row"><input type="checkbox" checked={item.webEnabled} onChange={event => update(key, item.id, { webEnabled: event.target.checked })} />{l("الموقع", "Website")}</label><label className="checkbox-row"><input type="checkbox" checked={item.pdfEnabled} onChange={event => update(key, item.id, { pdfEnabled: event.target.checked })} />PDF</label>{key === "projects" && <div className="field" style={{ marginTop: 10 }}><label htmlFor={`project-summary-${item.id}`}>{locale === "ar" ? l("ملخص مخصص لهذا البروفايل (بالعربية)", "Profile-specific summary (Arabic)") : l("ملخص مخصص لهذا البروفايل (بالإنجليزية)", "Profile-specific summary (English)")}</label><textarea id={`project-summary-${item.id}`} dir={locale === "ar" ? "rtl" : "ltr"} rows={3} value={(locale === "ar" ? item.summaryOverrideAr : item.summaryOverrideEn) ?? ""} onChange={event => update(key, item.id, locale === "ar" ? { summaryOverrideAr: event.target.value } : { summaryOverrideEn: event.target.value })} placeholder={locale === "ar" ? l("اتركه فارغًا لاستخدام ملخص المشروع المشترك", "Leave blank to use the shared project summary") : l("اتركه فارغًا لاستخدام ملخص المشروع المشترك", "Leave blank to use the shared project summary")} /></div>}{(key === "projects" || key === "experiences") && !!item.highlights?.length && <fieldset className="selection-highlights"><legend>{locale === "ar" ? l("النقاط الخاصة بهذا البروفايل", "Highlights for this profile") : l("النقاط الخاصة بهذا البروفايل", "Highlights for this profile")}</legend>{item.highlights.map(highlight => <div key={highlight.id}><label className="checkbox-row"><input type="checkbox" checked={highlight.selected} onChange={event => updateHighlight(key, item.id, highlight.id, { selected: event.target.checked, webEnabled: event.target.checked, pdfEnabled: event.target.checked })} />{locale === "ar" ? highlight.labelAr : highlight.labelEn}</label>{highlight.selected && <span className="inline-options"><label className="checkbox-row"><input type="checkbox" checked={highlight.webEnabled} onChange={event => updateHighlight(key, item.id, highlight.id, { webEnabled: event.target.checked })} />{l("الموقع", "Website")}</label><label className="checkbox-row"><input type="checkbox" checked={highlight.pdfEnabled} onChange={event => updateHighlight(key, item.id, highlight.id, { pdfEnabled: event.target.checked })} />PDF</label></span>}</div>)}</fieldset>}</>}</div><div className="row-actions"><button className="icon-button" disabled={index === 0} onClick={() => move(key, index, -1)} aria-label={`${l("رفع", "Move up")} ${locale === "ar" ? item.labelAr : item.labelEn}`}><ChevronUp /></button><button className="icon-button" disabled={index === value[key].length - 1} onClick={() => move(key, index, 1)} aria-label={`${l("خفض", "Move down")} ${locale === "ar" ? item.labelAr : item.labelEn}`}><ChevronDown /></button></div></div>) : <div className="empty-state">{l("لا يوجد محتوى مشترك في هذا القسم.", "No shared content in this section.")}</div>}</div>)}{mutation.isError && <div className="notice" role="alert">{localizeAdminError(mutation.error, l)}</div>}{mutation.isSuccess && <div className="notice success-notice">{l("تم حفظ انتقاء البروفايل دون نسخ الحقائق.", "Profile selection saved without duplicating facts.")}</div>}<button className="button button-secondary" disabled={mutation.isPending} onClick={() => mutation.mutate()}>{l("حفظ الانتقاء", "Save selection")}</button></section>;
}

type ContactSetting = { webEmail: boolean; pdfEmail: boolean; webPhone: boolean; pdfPhone: boolean; showLocation: boolean; showPhotoWeb: boolean };
function ProfileContactEditor({ profileId }: { profileId: string }) {
  const { l } = useAdminI18n();
  const query = useQuery({ queryKey: ["profile-contact", profileId], queryFn: () => api<ContactSetting>(`/api/v1/admin/profiles/${profileId}/contact`) });
  if (query.isLoading) return <LoadingState />; if (query.isError || !query.data) return <div className="notice" role="alert">{l("تعذر تحميل إعدادات الخصوصية.", "Unable to load privacy settings.")}</div>;
  return <ContactForm key={`${profileId}-${JSON.stringify(query.data)}`} profileId={profileId} initial={query.data} />;
}
function ContactForm({ profileId, initial }: { profileId: string; initial: ContactSetting }) {
  const { l } = useAdminI18n(); const [value, setValue] = useState(initial); const mutation = useMutation({ mutationFn: () => api<ContactSetting>(`/api/v1/admin/profiles/${profileId}/contact`, { method: "PUT", body: JSON.stringify(value) }) });
  const toggle = (key: keyof ContactSetting) => setValue(current => ({ ...current, [key]: !current[key] }));
  return <section style={{ marginTop: 28 }}><h3>{l("خصوصية بيانات التواصل", "Contact privacy")}</h3><div className="form-grid"><label className="checkbox-row"><input type="checkbox" checked={value.webEmail} onChange={() => toggle("webEmail")} />{l("البريد في الموقع", "Email on website")}</label><label className="checkbox-row"><input type="checkbox" checked={value.pdfEmail} onChange={() => toggle("pdfEmail")} />{l("البريد في PDF", "Email in PDF")}</label><label className="checkbox-row"><input type="checkbox" checked={value.webPhone} onChange={() => toggle("webPhone")} />{l("الهاتف في الموقع", "Phone on website")}</label><label className="checkbox-row"><input type="checkbox" checked={value.pdfPhone} onChange={() => toggle("pdfPhone")} />{l("الهاتف في PDF", "Phone in PDF")}</label><label className="checkbox-row"><input type="checkbox" checked={value.showLocation} onChange={() => toggle("showLocation")} />{l("إظهار الموقع الجغرافي", "Show location")}</label><label className="checkbox-row"><input type="checkbox" checked={value.showPhotoWeb} onChange={() => toggle("showPhotoWeb")} />{l("إظهار الصورة في الموقع", "Show photo on website")}</label></div>{mutation.isError && <div className="notice" role="alert">{localizeAdminError(mutation.error, l)}</div>}{mutation.isSuccess && <div className="notice success-notice">{l("تم حفظ إعدادات الخصوصية.", "Privacy settings saved.")}</div>}<button className="button button-secondary" disabled={mutation.isPending} onClick={() => mutation.mutate()}>{l("حفظ الخصوصية", "Save privacy settings")}</button></section>;
}

function ResumePaper({ value }: { value: Preview }) { return <div className="paper-shell"><article className="paper" lang={value.locale} dir={value.direction}><h1>{value.fullName}</h1><p><strong>{value.headline}</strong></p><p dir="ltr"><bdi>{[value.email, value.phone].filter(Boolean).join(" · ")}</bdi></p><h2>{value.locale === "ar" ? "الملخص المهني" : "Summary"}</h2><p>{value.summary}</p>{value.skills.length > 0 && <><h2>{value.locale === "ar" ? "المهارات التقنية" : "Technical Skills"}</h2><p>{value.skills.map(x => x.name).join(" · ")}</p></>}{value.projects.length > 0 && <><h2>{value.locale === "ar" ? "المشاريع" : "Projects"}</h2>{value.projects.map(project => <section key={project.name}><h3>{project.name}</h3><p>{project.summary}</p><ul>{project.highlights.map(item => <li key={item}>{item}</li>)}</ul></section>)}</>}</article></div>; }

function SitesPage() { return <SiteManager />; }

function SettingsPage() {
  const { l } = useAdminI18n();
  const [currentPassword, setCurrentPassword] = useState(""), [newPassword, setNewPassword] = useState(""); const mutation = useMutation({ mutationFn: () => api<void>("/api/v1/auth/password", { method: "PUT", body: JSON.stringify({ currentPassword, newPassword }) }) });
  const dataExport = useMutation({ mutationFn: () => api<unknown>("/api/v1/admin/data-export"), onSuccess: value => { const url = URL.createObjectURL(new Blob([JSON.stringify(value, null, 2)], { type: "application/json" })); const link = document.createElement("a"); link.href = url; link.download = `resume-data-${new Date().toISOString().slice(0, 10)}.json`; link.click(); URL.revokeObjectURL(url); } });
  return <><PageHeader title={l("الإعدادات", "Settings")} description={l("الأسرار لا تظهر في الواجهة؛ تُعرض الجاهزية فقط.", "Secrets are never shown in the interface; only readiness is displayed.")} /><section className="editor-panel"><h2>{l("تغيير كلمة المرور", "Change password")}</h2>{mutation.isError && <div className="notice" role="alert">{localizeAdminError(mutation.error, l)}</div>}{mutation.isSuccess && <div className="notice success-notice">{l("تم تغيير كلمة المرور وإبطال جميع الجلسات السابقة.", "Password changed and all previous sessions revoked.")}</div>}<div className="field"><label htmlFor="currentPassword">{l("كلمة المرور الحالية", "Current password")}</label><input id="currentPassword" dir="ltr" type="password" autoComplete="current-password" value={currentPassword} onChange={event => setCurrentPassword(event.target.value)} /></div><div className="field"><label htmlFor="newPassword">{l("كلمة المرور الجديدة", "New password")}</label><input id="newPassword" dir="ltr" type="password" autoComplete="new-password" value={newPassword} onChange={event => setNewPassword(event.target.value)} /><p className="field-help">{l("14 حرفًا على الأقل؛ يمكن اللصق واستخدام مدير كلمات المرور.", "At least 14 characters; pasting and password managers are supported.")}</p></div><button className="button button-primary" disabled={mutation.isPending || newPassword.length < 14} onClick={() => mutation.mutate()}>{l("تغيير وإبطال الجلسات", "Change and revoke sessions")}</button></section><section className="editor-panel" style={{ marginTop: 24 }}><h2>{l("تصدير بيانات المالك", "Export owner data")}</h2><p>{l("JSON منظم بلا كلمات مرور أو أسرار خدمات. هذا ليس بديلًا عن نسخة PostgreSQL احتياطية.", "Structured JSON without passwords or service secrets. This is not a replacement for a PostgreSQL backup.")}</p>{dataExport.isError && <div className="notice" role="alert">{localizeAdminError(dataExport.error, l)}</div>}<button className="button button-secondary" disabled={dataExport.isPending} onClick={() => dataExport.mutate()}>{dataExport.isPending ? l("جارٍ التصدير…", "Exporting…") : l("تصدير البيانات", "Export data")}</button></section></>;
}

function hasTranslation(person: Person, locale: ContentLocale) { const t = person.translations.find(x => x.locale === locale); return !!t?.fullName && !!t.defaultHeadline; }
function translationInput(person: Person, locale: ContentLocale) { const t = person.translations.find(x => x.locale === locale); return { fullName: t?.fullName ?? "", city: null, country: null, headline: t?.defaultHeadline ?? "", summary: t?.defaultSummary ?? "" }; }
